bash -lc 'python3 - <<"PY" 
import io,sys
p="/src/mupdf/source/fitz/load-bmp.c"
with open(p, "r", encoding="utf-8") as f:
    lines = f.readlines()
# Find function start index
start_idx = None
brace_depth = 0
for idx, line in enumerate(lines):
    if "bmp_read_palette(" in line and "static const unsigned char *" in lines[idx-1] if idx>0 else False:
        pass
# Simpler: locate first occurrence of the signature line
for i, line in enumerate(lines):
    if line.strip().endswith("bmp_read_palette(fz_context *ctx, struct info *info, const unsigned char *begin, const unsigned char *end, const unsigned char *p)"):
        start_idx = i
        break
if start_idx is None:
    for i, line in enumerate(lines):
        if line.strip().endswith("bmp_read_palette(fz_context *ctx, struct info *info, const unsigned char *begin, const unsigned char *end, const unsigned char *p)" ):
            start_idx = i
            break
# Now include the next line which is '{' line; determine end of function by brace matching
if start_idx is None:
    print("FUNCTION START NOT FOUND", file=sys.stderr)
    sys.exit(1)
# Move to the line with the opening brace
k = start_idx
if '{' not in lines[k+1]:
    # assume next line has '{'
    k_open = k+1
else:
    k_open = k+1
# Now walk with brace depth starting at 0 then plus the brace on k_open
depth = 0
if '{' in lines[k_open]:
    depth += lines[k_open].count('{')
    depth -= lines[k_open].count('}')
else:
    depth = 0
end_idx = None
idx = k_open+1
while idx < len(lines):
    s = lines[idx]
    depth += s.count('{')
    depth -= s.count('}')
    if depth == 0:
        end_idx = idx
        break
    idx += 1
if end_idx is None:
    print("END NOT FOUND", file=sys.stderr)
    sys.exit(1)
start_block = k
end_block = end_idx
print("Function block lines:", start_block, end_block)
old_func = lines[start_block:end_block+1]
new_func = '''static const unsigned char *
bmp_read_palette(fz_context *ctx, struct info *info, const unsigned char *begin, const unsigned char *end, const unsigned char *p)
{
	int i, expected, present, entry_size;
	const unsigned char *bitmap;

	entry_size = palette_entry_size(info);
	bitmap = begin + info->bitmapoffset;

	expected = fz_mini(info->colors, 1 << info->bitcount);
	if (expected == 0)
		expected = 1 << info->bitcount;

	/* Safely compute how many palette entries are present without writing past info */
	int diff = (int)(bitmap - p);
	if (diff < 0)
		present = 0;
	else
		present = diff / entry_size;
	if (present < 0) present = 0;
	if (present > expected) present = expected;

	for (i = 0; i < present; i++)
	{
		/* ignore alpha channel even if present */
		info->palette[3 * i + 0] = read8(p + i * entry_size + 2);
		info->palette[3 * i + 1] = read8(p + i * entry_size + 1);
		info->palette[3 * i + 2] = read8(p + i * entry_size + 0);
	}

	if (present < expected)
		bmp_load_default_palette(ctx, info, present);

	return p + present * entry_size;
}
'''
# Replace block
new_lines = lines[:start_block] + new_func.splitlines(True) + lines[end_block+1:]
with open(p, 'w', encoding='utf-8') as f:
    f.writelines(new_lines)
print("Patched file", p)
PY'

